import{c as e,Q as r,j as d,m as o}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse(`{"title":"R1-R12 行為條文 Token 效率深度研究（遵守度不降前提）","description":"","frontmatter":{"title":"R1-R12 行為條文 Token 效率深度研究（遵守度不降前提）","date":"2026-06-04T00:00:00.000Z","baseline_bytes":18455,"branch":"feature/autoload-slimming-apply","cap_bytes":19000,"headroom_bytes":545,"method":"3 researcher 並行（官方最佳實踐 + prompt-compression papers + 論文真實性驗證）+ core.md inline TYPE 盤點 + advisor 三輪校準","mode":"純研究 + 計劃書（零修改 auto-load）","question":"R1-R12 有什麼方法可以讓 Claude 遵守但不浪費 auto-load token？","type":"research","verified_papers":["arXiv:2604.07192 (Compact Constraint Encoding — EXISTS, 親驗 Cliff's δ<0.01)","arXiv:2512.17920 (CDCT U-curve — EXISTS, 親驗)"]},"headers":[],"relativePath":"research/reports/archive/2026-06-04-r1r12-token-efficiency-deep-research.md","filePath":"research/reports/archive/2026-06-04-r1r12-token-efficiency-deep-research.md","lastUpdated":1780842316000}`),a={name:"research/reports/archive/2026-06-04-r1r12-token-efficiency-deep-research.md"};function n(s,t,i,l,g,h){return r(),d("div",null,[...t[0]||(t[0]=[o(`<h1 id="r1-r12-行為條文-token-效率深度研究" tabindex="-1">R1-R12 行為條文 Token 效率深度研究 <a class="header-anchor" href="#r1-r12-行為條文-token-效率深度研究" aria-label="Permalink to &quot;R1-R12 行為條文 Token 效率深度研究&quot;">​</a></h1><blockquote><p><strong>核心問題</strong>：R1-R12 怎麼讓 Claude 遵守，但不浪費 auto-load token？ <strong>執行模式</strong>：純研究 + 計劃書，<strong>零修改 auto-load</strong>（使用者指令「產出獨立的研究報告和可執行計劃書」）。R1-R12 實際調整為下一個 gated session。</p></blockquote><hr><h2 id="_0-tl-dr-—-兩個-supersede-前一輪的關鍵發現-fail-loud-先行" tabindex="-1">0. TL;DR — 兩個 supersede 前一輪的關鍵發現（Fail-Loud 先行） <a class="header-anchor" href="#_0-tl-dr-—-兩個-supersede-前一輪的關鍵發現-fail-loud-先行" aria-label="Permalink to &quot;0. TL;DR — 兩個 supersede 前一輪的關鍵發現（Fail-Loud 先行）&quot;">​</a></h2><p>本輪證據<strong>翻轉</strong>了 #449（autoload-slimming）的兩個核心假設。使用者明令「遵照 papers + 官方最佳實踐」，故必須以證據為準，不繼承舊框架：</p><h3 id="發現-1-—-槓桿翻轉-proven-safe-是-reformat-不是-delete-rationale" tabindex="-1">發現 1 — 槓桿翻轉：proven-safe 是 REFORMAT，不是 DELETE-rationale <a class="header-anchor" href="#發現-1-—-槓桿翻轉-proven-safe-是-reformat-不是-delete-rationale" aria-label="Permalink to &quot;發現 1 — 槓桿翻轉：proven-safe 是 REFORMAT，不是 DELETE-rationale&quot;">​</a></h3><ul><li><strong>#449 框架</strong>：「刪 TYPE C/D rationale 回收 byte」。</li><li><strong>本輪一手證據反對此框架</strong>： <ul><li><strong>arXiv:2604.07192</strong>（親驗，Tencent 2026-04，11 模型/16 benchmark/830+ calls）：compact <strong>re-encoding</strong>（同 constraint 換緊湊格式）省 25-30% token，<strong>Constraint Satisfaction Rate 無統計顯著差異</strong>（Cliff&#39;s δ &lt; 0.01）。但它證明的是「<strong>重編碼</strong>安全」，<strong>不是「刪除 rationale」安全</strong>。</li><li><strong>官方 Finding 4.3</strong>（Anthropic prompt eng 文件）：「Providing context or motivation behind your instructions helps Claude better understand your goals」——舉例 bare <code>NEVER use ellipses</code>（弱）vs 解釋 TTS 引擎不懂省略號（強）。</li><li><strong>推論</strong>：12-Rule Canon 的設計核心「每條回答防止哪個失敗模式」<strong>正是這種 adherence-supporting motivation</strong>。刪掉「為何」= 刪掉官方背書的遵守支撐。</li></ul></li><li><strong>修正後槓桿</strong>：<strong>主力 = compact re-encode（verbose 散文 → 緊湊結構化，語義 + 枚舉 verbatim 保留）</strong>；刪除只限真正死重（TYPE D 過期日期/一次性決策史已在 MEMORY + TYPE C 跨檔重複）。<strong>不刪「為何」。</strong></li></ul><h3 id="發現-2-—-mast-κ-0-88-框架錯誤-須糾正不可繼承" tabindex="-1">發現 2 — MAST κ=0.88 框架錯誤，須糾正不可繼承 <a class="header-anchor" href="#發現-2-—-mast-κ-0-88-框架錯誤-須糾正不可繼承" aria-label="Permalink to &quot;發現 2 — MAST κ=0.88 框架錯誤，須糾正不可繼承&quot;">​</a></h3><ul><li><strong>#449 + MEMORY 多處</strong>把 MAST 的 κ=0.88 寫成「specification 品質指標」，作為「不可壓行為條文」的下限論證。</li><li><strong>本輪 researcher 親驗 arXiv:2503.13657</strong>：κ=0.88 是<strong>失敗分類法的標注者間一致性（inter-annotator agreement）</strong>，<strong>不是 spec-quality 指標</strong>。這是定義錯誤。</li><li><strong>後果</strong>：(a) 本報告下限<strong>重新接地</strong>在證據真正支持的東西（見 §3）；(b) <strong>flag MEMORY 待修</strong>（Lesson 待補：κ 誤讀散佈多處）。此為 Fail-Loud / Surface-Conflict，不靜默修。</li></ul><hr><h2 id="_1-全-auto-load-token-byte-量測-observe-使用者要求「對所有-autoload-token-量測」" tabindex="-1">1. 全 auto-load Token/Byte 量測（OBSERVE，使用者要求「對所有 autoload token 量測」） <a class="header-anchor" href="#_1-全-auto-load-token-byte-量測-observe-使用者要求「對所有-autoload-token-量測」" aria-label="Permalink to &quot;1. 全 auto-load Token/Byte 量測（OBSERVE，使用者要求「對所有 autoload token 量測」）&quot;">​</a></h2><p>驗證指令：<code>wc -c CLAUDE.md .claude/rules/{core,context-management,output-discipline,subagent-strategy}.md</code></p><table tabindex="0"><thead><tr><th>檔案</th><th style="text-align:right;">bytes</th><th style="text-align:right;">chars</th><th style="text-align:right;">est. tokens†</th><th style="text-align:right;">佔比</th><th>角色</th></tr></thead><tbody><tr><td><code>core.md</code></td><td style="text-align:right;">8,518</td><td style="text-align:right;">5,063</td><td style="text-align:right;">~2,700</td><td style="text-align:right;">46.2%</td><td>R1–R12 + Git + 生產紅線</td></tr><tr><td><code>subagent-strategy.md</code></td><td style="text-align:right;">3,855</td><td style="text-align:right;">2,390</td><td style="text-align:right;">~1,250</td><td style="text-align:right;">20.9%</td><td>委派 / fan-out / advisor</td></tr><tr><td><code>CLAUDE.md</code></td><td style="text-align:right;">2,585</td><td style="text-align:right;">1,944</td><td style="text-align:right;">~1,000</td><td style="text-align:right;">14.0%</td><td>Canon 表 + harness loop + 模式</td></tr><tr><td><code>context-management.md</code></td><td style="text-align:right;">2,007</td><td style="text-align:right;">1,234</td><td style="text-align:right;">~640</td><td style="text-align:right;">10.9%</td><td>token budget / compact / caching</td></tr><tr><td><code>output-discipline.md</code></td><td style="text-align:right;">1,490</td><td style="text-align:right;">785</td><td style="text-align:right;">~410</td><td style="text-align:right;">8.1%</td><td>輸出紀律</td></tr><tr><td><strong>總計</strong></td><td style="text-align:right;"><strong>18,455</strong></td><td style="text-align:right;">11,416</td><td style="text-align:right;"><strong>~6,000</strong></td><td style="text-align:right;">100%</td><td>vs cap 19,000，餘 <strong>545</strong></td></tr></tbody></table><p>† <strong>token 估算方法學</strong>（誠實標注）：本機無 tiktoken/ttok。混合中英；CJK 約 1.0-1.5 char/token、ASCII 約 4 char/token。粗估 ~6,000 tokens（±15%）。官方 cache 最低門檻 1,024 tokens（Opus/Sonnet）→ 遠超，<strong>精簡不碰 cache 底線</strong>（官方 Finding 3.1）。</p><h3 id="core-md-§r-各條-byte-分布-inline-盤點" tabindex="-1">core.md §R 各條 byte 分布（inline 盤點） <a class="header-anchor" href="#core-md-§r-各條-byte-分布-inline-盤點" aria-label="Permalink to &quot;core.md §R 各條 byte 分布（inline 盤點）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>條</th><th style="text-align:right;">byte</th><th>性質摘要</th><th>主要可 re-encode 內容</th></tr></thead><tbody><tr><td>§R1</td><td style="text-align:right;">1,039</td><td>假設顯露 + Ask-rate 校準 + 不可逆例外清單</td><td><strong>散文框架</strong>可緊湊化；<strong>枚舉清單 verbatim 保留</strong>（危險區）</td></tr><tr><td>§R3</td><td style="text-align:right;">692</td><td>外科刀 + 量化界線 + P0 grep 細節</td><td>量化數字保留；P0 流程散文可緊湊</td></tr><tr><td>§R2</td><td style="text-align:right;">548</td><td>Simplicity + Rule of 3 + 安全例外</td><td>散文可緊湊；Rule of 3 數字保留</td></tr><tr><td>§R12</td><td style="text-align:right;">548</td><td>Fail Loud + PGE + 截斷標示</td><td>散文可緊湊</td></tr><tr><td>§R7</td><td style="text-align:right;">286</td><td>衝突浮現 + 優先序</td><td>TODO 格式 verbatim 保留</td></tr><tr><td>§R11</td><td style="text-align:right;">275</td><td>規範優先</td><td>散文可緊湊</td></tr><tr><td>§R5</td><td style="text-align:right;">259</td><td>判斷 vs 決定</td><td>已精簡（範例對照）</td></tr><tr><td>§R8</td><td style="text-align:right;">259</td><td>改前先讀</td><td>已精簡</td></tr><tr><td>§R4</td><td style="text-align:right;">512</td><td>目標導向</td><td>驗證指令 verbatim 保留</td></tr><tr><td>§R9</td><td style="text-align:right;">190</td><td>測試驗證意圖</td><td>已精簡</td></tr><tr><td>§R10</td><td style="text-align:right;">178</td><td>Checkpoint</td><td>已精簡</td></tr></tbody></table><p><strong>關鍵</strong>：§R1 byte 最大，但大半是<strong>行為子規則 + 不可逆枚舉</strong>（DELETE/TRUNCATE/DROP...）→ 刪枚舉在<strong>危險區</strong>（見 §3 表）。<strong>biggest ≠ most compressible</strong>——讓危險表選目標，非 byte 排名。</p><hr><h2 id="_2-證據彙整-3-researcher-並行-advisor-校準" tabindex="-1">2. 證據彙整（3 researcher 並行 + advisor 校準） <a class="header-anchor" href="#_2-證據彙整-3-researcher-並行-advisor-校準" aria-label="Permalink to &quot;2. 證據彙整（3 researcher 並行 + advisor 校準）&quot;">​</a></h2><h3 id="_2-1-官方最佳實踐-anthropic-claude-code-一手" tabindex="-1">2.1 官方最佳實踐（Anthropic / Claude Code 一手） <a class="header-anchor" href="#_2-1-官方最佳實踐-anthropic-claude-code-一手" aria-label="Permalink to &quot;2.1 官方最佳實踐（Anthropic / Claude Code 一手）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Finding</th><th>來源</th><th>對本任務啟示</th></tr></thead><tbody><tr><td>O1</td><td>「Bloated CLAUDE.md → Claude ignores your actual instructions」；過長 = 重要規則被淹沒</td><td>code.claude.com/docs/best-practices</td><td><strong>官方支持精簡提升遵守</strong>（signal/noise）</td></tr><tr><td>O2</td><td>「Target under 200 lines per CLAUDE.md」</td><td>code.claude.com/docs/memory</td><td>200 行軟上限（本 workspace core.md 100 行 ✓）</td></tr><tr><td>O3</td><td>過長補救 = <strong>Ruthlessly prune</strong>，不是加更多規則</td><td>best-practices</td><td>精簡方向正確</td></tr><tr><td>O4</td><td><strong>加「為什麼/motivation」比加 CAPS 更提升遵守</strong></td><td>prompt eng 文件</td><td><strong>rationale 不該全刪</strong>（翻轉 #449）</td></tr><tr><td>O5</td><td>XML tags 減少 misinterpretation（無 A/B 數字）</td><td>prompt eng 文件</td><td>結構化方向，但無定量</td></tr><tr><td>O6</td><td>IMPORTANT/YOU MUST 在 <strong>CLAUDE.md 脈絡</strong>官方背書；但 API 工具觸發脈絡新模型應 dial back</td><td>best-practices vs prompt eng</td><td><strong>脈絡相依</strong>（auto-load 屬 CLAUDE.md 脈絡 → 保留強調詞合理）</td></tr><tr><td>O7</td><td>CLAUDE.md 是 <strong>user message 非 system prompt</strong>，無嚴格遵守保證</td><td>code.claude.com/docs/memory</td><td>架構事實：規則清晰度更重要</td></tr></tbody></table><h3 id="_2-2-學術-papers-親驗關鍵-2-篇" tabindex="-1">2.2 學術 papers（親驗關鍵 2 篇） <a class="header-anchor" href="#_2-2-學術-papers-親驗關鍵-2-篇" aria-label="Permalink to &quot;2.2 學術 papers（親驗關鍵 2 篇）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Paper</th><th>核心數字</th><th>安全/危險判定</th></tr></thead><tbody><tr><td>P1</td><td><strong>2604.07192</strong> Compact Constraint Encoding（親驗）</td><td>compact header 省 25-30% token，CSR <strong>無顯著差異 δ&lt;0.01</strong></td><td><strong>REFORMAT 安全</strong>（最直接一手）</td></tr><tr><td>P2</td><td><strong>2512.17920</strong> CDCT U-curve（親驗）</td><td>中間壓縮（~27 字模糊區）CC 最差（U 型，97.2% prevalence）</td><td><strong>壓到語義模糊 = 危險</strong></td></tr><tr><td>P3</td><td>2510.05106 Rule Encoding</td><td>低 syntactic entropy + anchor token（if/then）→ 提升 pointer fidelity</td><td><strong>條列/if-then 結構有理論優勢</strong></td></tr><tr><td>P4</td><td>2601.18554 MOSAIC</td><td>15+ constraints 全面劣化；Claude 有 recency effect</td><td><strong>不可把 12 條拆成更多</strong>；重要規則放首/末</td></tr><tr><td>P5</td><td>2605.06445 Constraint Decay</td><td>每加 1 constraint dimension -19.3pp</td><td>constraint <strong>數量</strong>傷遵守 → 不增量</td></tr><tr><td>P6</td><td>2407.08892 Prompt Compression 比較</td><td>SQL CREATE TABLE 內 token 被移除 → 嚴重劣化</td><td><strong>definition/枚舉內 token 高危</strong></td></tr><tr><td>P7</td><td>2403.12968 LLMLingua-2</td><td>均勻 token 剪法，指令不享保護</td><td><strong>自動壓縮工具不適用規則檔</strong></td></tr><tr><td>P8</td><td>2502.14255 Prompt Length</td><td>縮短「含資訊」指令一致劣化</td><td>砍<strong>有資訊</strong>內容危險（≠砍冗餘措辭）</td></tr></tbody></table><h3 id="_2-3-已知研究空白-誠實標注" tabindex="-1">2.3 已知研究空白（誠實標注） <a class="header-anchor" href="#_2-3-已知研究空白-誠實標注" aria-label="Permalink to &quot;2.3 已知研究空白（誠實標注）&quot;">​</a></h3><ul><li><strong>無 paper 直接實證「移除每條規則的 rationale 對 adherence 的影響」</strong>。間接證據（P1 + O4）傾向「constraint 清晰度 &gt; 解釋長度」，但官方 O4 明確「motivation 提升遵守」→ <strong>淨判定：保留 rationale，只 re-encode 表達</strong>。</li></ul><hr><h2 id="_3-安全-危險分類表-identify-→-這是-apply-的-gate" tabindex="-1">3. 安全/危險分類表（IDENTIFY → 這是 APPLY 的 gate） <a class="header-anchor" href="#_3-安全-危險分類表-identify-→-這是-apply-的-gate" aria-label="Permalink to &quot;3. 安全/危險分類表（IDENTIFY → 這是 APPLY 的 gate）&quot;">​</a></h2><blockquote><p>由危險表（非 byte 排名）決定可動目標。下限<strong>重新接地</strong>（不用誤讀的 MAST κ）。</p></blockquote><table tabindex="0"><thead><tr><th>操作</th><th>判定</th><th>證據</th></tr></thead><tbody><tr><td>verbose 散文 → 緊湊結構化（語義保留）</td><td>✅ <strong>安全</strong></td><td>P1 (δ&lt;0.01) + P3</td></tr><tr><td>移除跨檔<strong>重複</strong>陳述（同義保留一處）</td><td>✅ <strong>安全</strong></td><td>TYPE C；#449 C3 已驗</td></tr><tr><td>移除<strong>過期日期/一次性決策史</strong>（已在 MEMORY）</td><td>✅ <strong>安全</strong></td><td>TYPE D；#449 C1 已驗</td></tr><tr><td>保留條文 verbatim、砍 rationale 解釋</td><td>⚠️ <strong>不建議</strong></td><td>O4 反對（motivation 助遵守）；無 paper 支持移除安全</td></tr><tr><td>壓條文到語義模糊（~27 字 U-curve 區）</td><td>❌ <strong>危險</strong></td><td>P2 CDCT</td></tr><tr><td>移除<strong>枚舉清單</strong>（DELETE/TRUNCATE/DROP、不可逆動作）</td><td>❌ <strong>危險</strong></td><td>P6 (2407.08892) + 2304.08467</td></tr><tr><td>移除<strong>驗證指令字面</strong>（healthcheck/wc -c/grep）</td><td>❌ <strong>危險</strong></td><td>spec 可驗證性（R4/R12）</td></tr><tr><td>增加 constraint 數量 / 拆條文</td><td>❌ <strong>危險</strong></td><td>P4 (15+) + P5 (-19.3pp/dim)</td></tr><tr><td>重要規則移到中間位置</td><td>❌ <strong>危險</strong></td><td>P4 primacy/recency</td></tr></tbody></table><p><strong>下限重述</strong>（取代誤讀的 MAST κ=0.88）：</p><ol><li>行為<strong>語義</strong>不可變（CDCT U-curve：壓到模糊最傷）；</li><li><strong>枚舉/驗證指令 verbatim 保留</strong>（compression paper：definition token 高危）；</li><li><strong>不增 constraint 數</strong>（MOSAIC/Constraint Decay）；</li><li><strong>rationale 保留</strong>（官方 O4：motivation 助遵守）——只改表達不刪意義。</li></ol><hr><h2 id="_4-可精簡空間估算-保守" tabindex="-1">4. 可精簡空間估算（保守） <a class="header-anchor" href="#_4-可精簡空間估算-保守" aria-label="Permalink to &quot;4. 可精簡空間估算（保守）&quot;">​</a></h2><p>僅限「✅ 安全」操作（re-encode + 去重 + 去死重），<strong>不碰 ⚠️/❌</strong>：</p><table tabindex="0"><thead><tr><th>區塊</th><th>操作</th><th style="text-align:right;">估算回收</th></tr></thead><tbody><tr><td>§R1/§R2/§R3/§R12 散文框架 → 緊湊（語義+枚舉 verbatim 保留）</td><td>re-encode</td><td style="text-align:right;">~200-350 B</td></tr><tr><td>長期記憶回路 (616B) 操作散文緊湊化</td><td>re-encode</td><td style="text-align:right;">~80-120 B</td></tr><tr><td>Git 工作流程 (1033B) PR 衝突段措辭</td><td>re-encode</td><td style="text-align:right;">~50-80 B</td></tr><tr><td>跨檔殘餘重複（context-mgmt ↔ CLAUDE.md compact hint）</td><td>去重</td><td style="text-align:right;">~50-100 B</td></tr><tr><td><strong>合計（保守）</strong></td><td></td><td style="text-align:right;"><strong>~380-650 B</strong></td></tr></tbody></table><p><strong>注意</strong>：估算偏保守且<strong>低於</strong> #449 的 500B/單輪——因本輪<strong>禁止刪 rationale</strong>（最大宗 byte 來源），只能 re-encode。<strong>這是正確的 trade-off：少省 byte，換不傷遵守</strong>（使用者要的是「遵守但不浪費」，遵守優先）。</p><hr><h2 id="_5-裁決-propose" tabindex="-1">5. 裁決（PROPOSE） <a class="header-anchor" href="#_5-裁決-propose" aria-label="Permalink to &quot;5. 裁決（PROPOSE）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>問題</th><th>裁決</th></tr></thead><tbody><tr><td>R1-R12 能在不傷遵守下省 token？</td><td>✅ <strong>能，但限 re-encode 不限 delete-rationale</strong></td></tr><tr><td>主力槓桿</td><td><strong>compact re-encode</strong>（P1 親驗安全）</td></tr><tr><td>最大 byte（§R1）可大砍？</td><td>❌ 不可——大半是枚舉/行為子規則（危險區）</td></tr><tr><td>下限</td><td>CDCT 語義 + 枚舉/驗證指令 verbatim + 不增 constraint 數 + 保留 motivation</td></tr><tr><td>本輪交付</td><td><strong>報告 + 計劃書</strong>；R1-R12 edits = 下一 gated session（鏡像 #446）</td></tr><tr><td>附帶</td><td><strong>flag MEMORY κ=0.88 誤讀待修</strong>（Fail-Loud）</td></tr></tbody></table><p><strong>不建議</strong>：① 為省 byte 刪 rationale（官方 O4 反對）；② 用自動壓縮工具（LLMLingua 類，P7 不適用規則）；③ 把精簡當遵守度優化的主手段（官方 O7：clarity 才是）。</p><hr><h2 id="_6-後續-計劃書-handoff" tabindex="-1">6. 後續（計劃書 handoff） <a class="header-anchor" href="#_6-後續-計劃書-handoff" aria-label="Permalink to &quot;6. 後續（計劃書 handoff）&quot;">​</a></h2><p>可執行計劃書見：<code>2026-06-04-r1r12-token-efficiency-execution-plan.md</code>（逐項 re-encode 候選 + 危險表 gate + falsifiable prediction + eval 驗證遵守度不降）。</p><p><strong>驗證指令（基線）</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CLAUDE.md</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .claude/rules/{core,context-management,output-discipline,subagent-strategy}.md</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 18455</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;^## §R&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .claude/rules/core.md</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 11（+R6 在 context-mgmt）</span></span></code></pre></div><hr><h2 id="附錄-論文清單-驗證狀態" tabindex="-1">附錄：論文清單（驗證狀態） <a class="header-anchor" href="#附錄-論文清單-驗證狀態" aria-label="Permalink to &quot;附錄：論文清單（驗證狀態）&quot;">​</a></h2><ul><li>✅ 親驗 EXISTS：<code>2604.07192</code>（Compact Constraint Encoding, Tencent 2026-04）、<code>2512.17920</code>（CDCT, 2025-12）</li><li>二手引用（researcher 標注，未逐一親驗）：<code>2503.13657</code> MAST、<code>2510.05106</code>、<code>2601.18554</code> MOSAIC、<code>2605.06445</code>、<code>2407.08892</code>、<code>2403.12968</code>、<code>2502.14255</code>、<code>2411.10541</code>、<code>2304.08467</code> GIST、<code>2310.05736</code> LLMLingua、<code>2304.12102</code> Selective-Context</li><li><strong>κ=0.88 修正</strong>：MAST 的 κ 是 inter-annotator agreement，非 spec-quality（親驗 abstract 確認）</li></ul>`,48)])])}const u=e(a,[["render",n]]);export{p as __pageData,u as default};
